DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261004073302_InitialCreate') THEN
    CREATE INDEX "IX_Products_Category" ON "Products" ("Category");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261004073302_InitialCreate') THEN
    PERFORM setval(
        pg_get_serial_sequence('"Products"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Products") + 1,
            nextval(pg_get_serial_sequence('"Products"', 'Id'))),
        false);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261004073302_InitialCreate') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261004073302_InitialCreate', '10.0.12');
    END IF;
END $EF$;
COMMIT;

